import sys
import json

with open("/tmp/opencode/all_trees.json") as f:
    trees = json.load(f)

if len(sys.argv) == 1:
    # Print depth 0 and depth 1 summary for all 20 applicants
    for app_id in range(1, 21):
        t = trees[str(app_id)]
        c0 = t["check"]
        b_summary = []
        for b in range(6):
            sub = t["bands"][str(b)]
            if isinstance(sub, str):
                b_summary.append(f"{b}:{sub[:3].upper()}")
            else:
                # also show depth-2 for this band
                sub2 = []
                for b2 in range(6):
                    s2 = sub["bands"][str(b2)]
                    sub2.append(f"{b2}:{s2[:3].upper() if isinstance(s2, str) else s2['check'][:3]}")
                b_summary.append(f"{b}:{sub['check']}[{','.join(sub2)}]")
        print(f"App {app_id:2d}: 1st={c0:6s} | " + " | ".join(b_summary))
else:
    app_id = sys.argv[1]
    bands = sys.argv[2:]
    node = trees[app_id]
    for b in bands:
        node = node["bands"][b]
    if isinstance(node, str):
        print(f"App {app_id} after {bands} -> DECIDE: {node}")
    else:
        print(f"App {app_id} after {bands} -> RUN_CHECK: {node['check']}")
        for b, sub in node["bands"].items():
            if isinstance(sub, str):
                print(f"  if band {b} -> DECIDE: {sub}")
            else:
                s2 = [f"{b2}:{v if isinstance(v, str) else v['check']}" for b2, v in sub["bands"].items()]
                print(f"  if band {b} -> RUN_CHECK: {sub['check']} ({', '.join(s2)})")

